// expect: exit 0
// screen: 0 sqrt(2) = 1.41421356
// screen: 1 sqrt(16) = 4.00
float root(float x)
{
    float r = x;
    int i;
    for (i = 0; i < 20; i++)
        r = (r + x / r) / 2;
    return r;
}
int main(void)
{
    cls();
    printf("sqrt(2) = %.8f\n", root(2));
    printf("sqrt(16) = %.2f\n", root(16));
    return 0;
}
